{"implementation": "import math
def solve(case):
    matrix = case["matrix"]
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError("matrix must be nonempty list of lists")
    n = len(matrix)
    m = len(matrix[0])
    if m == 0 or not all(len(row) == m for row in matrix):
        raise ValueError("matrix must be rectangular with at least one column")
    df = [0] * m
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf = [math.log(1 + n / (1 + d)) for d in df]
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = [val * idf[j] for j, val in enumerate(row)]
        weighted_matrix.append(weighted_row)
        row_degree.append(sum(weighted_row))
    idf = [round(x, 6) for x in idf]
    weighted_matrix = [[round(x, 6) for x in row] for row in weighted_matrix]
    row_degree = [round(x, 6) for x in row_degree]
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted_matrix}"}
